// Crusaders Mainframe — the electrical level of a GPIO pin.
//
// WHY THIS EXISTS
// ---------------
// Two of the four peripherals on this board are wired inverted: the relay
// module closes its contact when driven LOW, and the buttons are INPUT_PULLUP
// so a pressed button reads LOW. Both of those are the OPPOSITE of what a
// `bool` called `on` or `pressed` reads like at the call site.
//
// A bool cannot hold that distinction. `digitalWrite(pin, on)` compiles, looks
// right, and turns four courts' lights on when the system wanted them off — for
// up to the hard cap, on a live electrical circuit. So the pin level gets its
// own type, and the translation between "logical on" and "electrical level"
// happens in exactly one named place per peripheral (see relayLevelFor() in
// hal/Relay.h and kButtonPressedLevel in hal/Button.h).
//
// Rejected: a plain `bool activeLow` flag passed around beside the value. It
// keeps the two facts in separate variables, which is how they get separated.
//
// No Arduino headers. Compiles for AVR, Xtensa and the host test runner.

#ifndef CRUSADERS_HAL_PINLEVEL_H
#define CRUSADERS_HAL_PINLEVEL_H

#include <stdint.h>

namespace hal {

/// A digital pin's electrical level. The values match Arduino's LOW/HIGH so a
/// driver can cast once at the boundary, but nothing in pure lib/ depends on
/// that — the enum is the contract.
enum class PinLevel : uint8_t { kLow = 0U, kHigh = 1U };

/// Only for the thin drivers in arduino_hal/, which must hand an int to
/// digitalWrite(). Pure code compares PinLevel values directly and never calls
/// this.
inline uint8_t toDigital(PinLevel level) {
  return static_cast<uint8_t>(level);
}

} // namespace hal

#endif // CRUSADERS_HAL_PINLEVEL_H
